  method: 'POST',
  headers: {accept: 'application/json', 'content-type': 'application/json'},
  body: JSON.stringify({
    object: 'widget',
    id: 'string',
    color: 'red',
    parts: [
      {
        object: 'widget_part',
        id: 'string',
        snapshot: {taken_at: '2019-08-24T14:15:22Z'}
      }
    ]
  })
};

fetch('https://api.example.com/v1/widgets', options)
  .then(res => res.json())
  .then(res => console.log(res))
  .catch(err => console.error(err));

